// Rolling one-hour delivery limit per channel, user, and message category.
// `store` is any Map-like object; timestamps stay in it so callers can share
// one store across notifiers.
function createHourlyThrottle({ channel, store, now, maxPerHour }) {
  function keyFor(user, message) {
    const category = message.category || 'general';
    return `${channel}:${user.id}:${category}`;
  }

  function check(user, message, options) {
    if (options.force || message.priority === 'urgent') {
      return { throttled: false };
    }

    const key = keyFor(user, message);
    const current = now().getTime();
    const records = (store.get(key) || []).filter(ts => current - ts < WINDOW_MS);

    if (records.length >= maxPerHour) {
      return {
        throttled: true,
        reason: `${channel} hourly limit reached`,
        retryAt: new Date(records[0] + WINDOW_MS).toISOString()
      };
    }

    return { throttled: false };
  }

  function record(user, message) {
    const key = keyFor(user, message);
    const records = store.get(key) || [];
    records.push(now().getTime());
    store.set(key, records);
  }

  return { check, record };
}

